                        audio_path,
                        float(row_time),
                        row_candidate,
                        boom_candidates=boom_rows,
                        context_candidates=[dict(selected)] + earlier_rows[:8],
                        profile=profile if isinstance(profile, Mapping) else {},
                        beatgrid=beatgrid if isinstance(beatgrid, Mapping) else {},
                        bpm=bpm,
                        clock_zero_sec=clock_zero,
                        rejected_sections=[],
                        source="visual_first_credible_body_front_edge_repair",
                        reason="earlier proven body front restored over later final repair",
                        max_abs_offset_sec=0.350,
