            repaired_selected = dict(selected)
            repaired_selected["timestamp"] = float(repaired_marker)
            repaired_selected["snapped_sec"] = float(repaired_marker)
            repaired_selected["time_sec"] = float(repaired_marker)
            repaired_selected["microaligned_time"] = float(repaired_marker)
            repaired_selected["visual_raw_chunk_time"] = float(repaired_marker)
            original_repair_source = str(repaired_selected.get("selected_by") or "")
            preserve_nearest_mask_source = bool(
                original_repair_source == "visual_final_contract_gui_mask_nearest_repair"
                or (
                    original_repair_source == "visual_first_credible_body_front_edge_repair"
                    and bool(_visual_components(repaired_selected).get("first_credible_body_front_edge_repair"))
                )
            )
            preserve_full_track_source = bool(
                original_repair_source == "visual_full_track_stronger_boom_front_edge"
                and bool(_visual_components(repaired_selected).get("full_track_stronger_boom_front_edge_repair"))
            )
            repaired_selected["selected_by"] = (
                "visual_final_contract_gui_mask_nearest_repair"
                if preserve_nearest_mask_source
                else original_repair_source
                if preserve_full_track_source
                else "visual_final_contract_visible_signal_repair"
            )
