            relieved_gui["passes"] = True
            relieved_gui["reasons"] = []
            relieved_gui["relieved_reasons"] = [
                str(reason) for reason in gui_contract_proof.get("reasons") or [] if str(reason)
            ]
            relieved_gui["accepted_by_full_track_stable_wide_zoom_conflict"] = True
            gui_contract_proof = relieved_gui
            selected["gui_mask_proof"] = dict(gui_contract_proof)
